@Override
public ResultData hasH5Menu(String componentIdentification, String componentVersion, String username) {
    if(StrUtil.isBlank(componentIdentification, componentVersion, username)){
        logger.info("hasH5Menu fail. componentIdentification and componentVersion and username are not null");
        return new ResultData(ErrorCode.PARAMS_ERROR.getErrorCode(),"componentIdentification and componentVersion and username are not null");
    }
    boolean inWhitelist = isWebH5GroupEnabled(componentIdentification, componentVersion);
    Map<String, Object> resultMap = new HashMap<>();
    resultMap.put("inWhitelist", inWhitelist);
    //非白名单或框架类型非 web 的组件不弹窗，直接返回 false
    if(!inWhitelist){
        resultMap.put("hasH5Menu", false);
        resultMap.put("hasReaded", false);
        return ErrorCode.SUCCESS.returnResultData(resultMap);
    }
    boolean hasH5Menu = false;
    List<Map<String, Object>> menuMapList = componentModelClient.queryComponentMenu(componentIdentification, componentVersion);
    //白名单内：对 c_menu_group 为 null 的存量菜单做 web/h5 分组的填充回写，仅填 null 不影响已配置菜单
    if (menuMapList != null && menuMapList.size() > 0) {
        this.fillMenuGroupIfNull(componentIdentification, menuMapList);
        for(Map<String, Object> map : menuMapList){
            if("h5menus".equals(String.valueOf(map.get("c_menu_group")))){
                hasH5Menu = true;
                break;
            }
        }
    }
    //存在 H5 菜单时，判断当前用户是否已读
    boolean hasReaded = false;
    if(hasH5Menu){
        hasReaded = componentH5MenuReadDao.existsByComponentIdAndVersionNoAndUserName(componentIdentification, componentVersion, username);
    }
    logger.info("hasH5Menu result:{}, hasReaded:{} componentIdentification:{} componentVersion:{}", hasH5Menu, hasReaded, componentIdentification, componentVersion);
    resultMap.put("hasH5Menu", hasH5Menu);
    resultMap.put("hasReaded", hasReaded);
    return ErrorCode.SUCCESS.returnResultData(resultMap);
}

@Override
public ResultData markReaded(String componentIdentification, String componentVersion, String username) {
    if(StrUtil.isBlank(componentIdentification, componentVersion, username)){
        logger.info("markReaded fail. componentIdentification and componentVersion and username are not null");
        return new ResultData(ErrorCode.PARAMS_ERROR.getErrorCode(),"componentIdentification and componentVersion and username are not null");
    }
    //非白名单或框架类型非 web 的组件直接返回成功，不写库
    if(!isWebH5GroupEnabled(componentIdentification, componentVersion)){
        logger.info("markReaded not in whitelist, skip write. componentIdentification:{} componentVersion:{} username:{}", componentIdentification, componentVersion, username);
        return ErrorCode.SUCCESS.returnResultData(true);
    }
    //已存在则不再重复写入
    if(!componentH5MenuReadDao.existsByComponentIdAndVersionNoAndUserName(componentIdentification, componentVersion, username)){
        ComponentH5MenuReadEntity entity = new ComponentH5MenuReadEntity();
        entity.setComponentId(componentIdentification);
        entity.setVersionNo(componentVersion);
        entity.setUserName(username);
        componentH5MenuReadDao.save(entity);
    }
    logger.info("markReaded success. componentIdentification:{} componentVersion:{} username:{}", componentIdentification, componentVersion, username);
    return ErrorCode.SUCCESS.returnResultData(true);
}
